from urllib.parse import unquote

def decode_component(value):
    """Decode one component from an application/x-www-form-urlencoded field."""
    return unquote(value)
import unittest
from form import form_plus_decoding as core

class OrdinaryTests(unittest.TestCase):
    def test_ordinary_0(self):
        self.assertEqual(core.decode_component("abc"),"abc")

    def test_ordinary_1(self):
        self.assertEqual(core.decode_component(""),"")

    def test_ordinary_2(self):
        self.assertEqual(core.decode_component("a%20b"),"a b")

    def test_ordinary_3(self):
        self.assertEqual(core.decode_component("%2B"),"+")

    def test_ordinary_4(self):
        self.assertEqual(core.decode_component("%41"),"A")
